(835961, 95051, 22613, '<td valign="top">very nice.</td>', 'very nice.', '2004-08-02 01:03:49.000000', NULL, 1),
(835964, 94711, 23929, '<td valign="top">I was going to do a similar shot. We have these guys come in every evening but did they come in yesterday - NO! Little buggers. Aren''t they the most incredible birds. I just love them. I live on the far north coast of NSW and have added this to my favs. Love it.</td>', 'I was going to do a similar shot. We have these guys come in every evening but did they come in yesterday - NO! Little buggers. Aren''t they the most incredible birds. I just love them. I live on the far north coast of NSW and have added this to my favs. Love it.', '2004-08-02 01:04:21.000000', NULL, 1),
(835969, 95307, 17874, '<td valign="top">This would have been more effective with a white or cream background, in my opinion. The red is quite distracting.</td>', 'This would have been more effective with a white or cream background, in my opinion. The red is quite distracting.', '2004-08-02 01:08:19.000000', NULL, 1),
(835972, 94751, 17874, '<td valign="top">It must have been hard to get this shot! You did an ice job.</td>', 'It must have been hard to get this shot! You did an ice job.', '2004-08-02 01:09:24.000000', NULL, 1),
(835973, 94529, 19670, '<td valign="top">Blue is not really a major component of this shot...I do like the raggedy sneakers as a subject, though.</td>', 'Blue is not really a major component of this shot...I do like the raggedy sneakers as a subject, though.', '2004-08-02 01:09:30.000000', NULL, 1),
(835974, 95121, 13384, '<td valign="top">difficult subject here</td>', 'difficult subject here', '2004-08-02 01:09:32.000000', NULL, 1),
