(835979, 94920, 22748, '<td valign="top">Nice, super sharp capture. Great placement of the planes within the frame. Nice contrast between the bright whites &amp; reds and the blue sky. Only, too bad the top of the wings are in the shade, it dulls the nice reds a bit.</td>', 'Nice, super sharp capture. Great placement of the planes within the frame. Nice contrast between the bright whites & reds and the blue sky. Only, too bad the top of the wings are in the shade, it dulls the nice reds a bit.', '2004-08-02 01:10:11.000000', NULL, 1),
(835980, 94775, 13384, '<td valign="top">seriously not on task here</td>', 'seriously not on task here', '2004-08-02 01:10:30.000000', NULL, 1),
(835981, 94889, 19670, '<td valign="top">More green than blue, and I''m not sure about the soft focus.</td>', 'More green than blue, and I''m not sure about the soft focus.', '2004-08-02 01:11:23.000000', NULL, 1),
(835982, 95285, 16230, '<td valign="top">I was feeling a little blue until I saw this photo. Very tasty!</td>', 'I was feeling a little blue until I saw this photo. Very tasty!', '2004-08-02 01:11:29.000000', NULL, 1),
