(836136, 94638, 6008, '<td valign="top">I like the color and the depth of field. The focus on the element is great, although the OOF on the black bit is a little distracting. Like the way the light reflects and clings to the transparent item too. A tad more negative space on the left so the item isnt on the edge/cropped would have been preferred.</td>', 'I like the color and the depth of field. The focus on the element is great, although the OOF on the black bit is a little distracting. Like the way the light reflects and clings to the transparent item too. A tad more negative space on the left so the item isnt on the edge/cropped would have been preferred.', '2004-08-02 01:41:00.000000', NULL, 1),
(836139, 94700, 22656, '<td valign="top">Elegant</td>', 'Elegant', '2004-08-02 01:41:39.000000', NULL, 1),
