(836143, 94796, 6008, '<td valign="top">The car looks neat, has a great color, no bad reflections or annoying light flares. Unfortunately the background is a little busy and the people give it that ''snapshot'' look. Blurring the background more would have helped some, or else finding a different angle to avoid most of the background clutter.</td>', 'The car looks neat, has a great color, no bad reflections or annoying light flares. Unfortunately the background is a little busy and the people give it that ''snapshot'' look. Blurring the background more would have helped some, or else finding a different angle to avoid most of the background clutter.', '2004-08-02 01:42:54.000000', NULL, 1),
(836144, 94794, 13384, '<td valign="top">i realize this is the moon and all, but should this be a genuine submission?</td>', 'i realize this is the moon and all, but should this be a genuine submission?', '2004-08-02 01:42:54.000000', NULL, 1),
(836148, 94882, 23294, '<td valign="top">oh man, pacman is the bomb!</td>', 'oh man, pacman is the bomb!', '2004-08-02 01:43:41.000000', NULL, 1),
