(837657, 94892, 19011, '<td valign="top">Too much rocks for my liking. Would be an excellent pic if you crop only the top half.</td>', 'Too much rocks for my liking. Would be an excellent pic if you crop only the top half.', '2004-08-02 17:33:02.000000', NULL, 1),
(837658, 95024, 19011, '<td valign="top">Top shot. I really love this shot!!!!</td>', 'Top shot. I really love this shot!!!!', '2004-08-02 17:33:54.000000', NULL, 1),
(837661, 95027, 11800, '<td valign="top">I like the composition, the waves, the colors and the flare/drops behind the little guy.  The clarity is great also. It''s a good inventive shot. Imo, what could be improved is the glare on the water and to a lesser extent the hot spots on the bludolph. Some ways of controling the glare: use a circular polarizer, place some material between the light sorce and the water or if they don''t work, clone them out on ps. Still, I do like it enough to give a 7.</td>', 'I like the composition, the waves, the colors and the flare/drops behind the little guy.  The clarity is great also. It''s a good inventive shot. Imo, what could be improved is the glare on the water and to a lesser extent the hot spots on the bludolph. Some ways of controling the glare: use a circular polarizer, place some material between the light sorce and the water or if they don''t work, clone them out on ps. Still, I do like it enough to give a 7.', '2004-08-02 17:34:03.000000', NULL, 1),
(837665, 94975, 11800, '<td valign="top">Pleasing abstract.</td>', 'Pleasing abstract.', '2004-08-02 17:37:37.000000', NULL, 1),
