(837670, 94802, 5354, '<td valign="top">missed a bit at tthe top of the left hand petal.<br/> <br/>Nice shot though</td>', 'missed a bit at tthe top of the left hand petal. Nice shot though', '2004-08-02 17:39:37.000000', NULL, 1),
(837672, 95093, 8139, '<td valign="top">Very expressive baby. And good setup.</td>', 'Very expressive baby. And good setup.', '2004-08-02 17:40:12.000000', NULL, 1),
(837673, 95140, 23146, '<td valign="top">Nice color combination although I think it´s a little bit out of focus</td>', 'Nice color combination although I think it´s a little bit out of focus', '2004-08-02 17:41:48.000000', NULL, 1),
(837680, 94721, 5354, '<td valign="top">He needs to be further back in the frame, give him some space to skate into. Thats a cardianl rule for composition - an action shot has to have room for the action to move into. Try it and see what a difference it makes</td>', 'He needs to be further back in the frame, give him some space to skate into. Thats a cardianl rule for composition - an action shot has to have room for the action to move into. Try it and see what a difference it makes', '2004-08-02 17:46:15.000000', NULL, 1),
(837681, 94687, 8139, '<td valign="top">From a jazz lover, this speaks to me.Good DOF and diagonal lines. Intelligent use of selective desaturation.10</td>', 'From a jazz lover, this speaks to me.Good DOF and diagonal lines. Intelligent use of selective desaturation.10', '2004-08-02 17:46:41.000000', NULL, 1),
(837695, 94932, 11800, '<td valign="top">Think I would rather see it with it''s natural colors. Nice capture of the raindrops with good dof. The tones seem a little flat.</td>', 'Think I would rather see it with it''s natural colors. Nice capture of the raindrops with good dof. The tones seem a little flat.', '2004-08-02 17:51:19.000000', NULL, 1),
