(840009, 94934, 24435, '<td valign="top">the contrast is lovely!</td>', 'the contrast is lovely!', '2004-08-03 18:35:52.000000', NULL, 1),
(840010, 94633, 22748, '<td valign="top">Very nice abstractish shot. I love the brightness and colors here. And yes, I wonder what it is...</td>', 'Very nice abstractish shot. I love the brightness and colors here. And yes, I wonder what it is...', '2004-08-03 18:36:11.000000', NULL, 1),
