(840013, 94638, 24435, '<td valign="top">love the title!</td>', 'love the title!', '2004-08-03 18:37:01.000000', NULL, 1),
(840014, 95162, 22748, '<td valign="top">Nice studio shot. Lighting''s a tiny bit harsh, it would be nice to get rid of the shadows somehow and make the background brighter and more evenly white. Good otherwise.</td>', 'Nice studio shot. Lighting''s a tiny bit harsh, it would be nice to get rid of the shadows somehow and make the background brighter and more evenly white. Good otherwise.', '2004-08-03 18:37:13.000000', NULL, 1),
(840015, 94752, 22748, '<td valign="top">Such deep blue! It''s great. The old lid is a great detail there too.</td>', 'Such deep blue! It''s great. The old lid is a great detail there too.', '2004-08-03 18:37:50.000000', NULL, 1),
(840018, 95242, 22748, '<td valign="top">Great composition. The very bright white is really nice. There''s a little excess blue tint at the upper left corner outside the border, though that is a little distracting. The border is clean and tidy though and adds to the image''s simple elegance.</td>', 'Great composition. The very bright white is really nice. There''s a little excess blue tint at the upper left corner outside the border, though that is a little distracting. The border is clean and tidy though and adds to the image''s simple elegance.', '2004-08-03 18:38:58.000000', NULL, 1),
(840020, 94529, 22748, '<td valign="top">Heh, time for some new shoes, maybe? Just maybe. This image is okay, but the blue needs to be more of a focal point of the composition. Perhaps a really close up shot of the sock and shoe of one foot would be more powerful.</td>', 'Heh, time for some new shoes, maybe? Just maybe. This image is okay, but the blue needs to be more of a focal point of the composition. Perhaps a really close up shot of the sock and shoe of one foot would be more powerful.', '2004-08-03 18:40:20.000000', NULL, 1),
(840023, 94745, 22748, '<td valign="top">Hehe, interesting shot. The lighting is a little harsh, must be from a flash maybe, but not too bad.</td>', 'Hehe, interesting shot. The lighting is a little harsh, must be from a flash maybe, but not too bad.', '2004-08-03 18:41:31.000000', NULL, 1),
