(840145, 95330, 22748, '<td valign="top">Nice, I like how the frame is filled. Pretty even lighting, maybe more diffusion would be nice or a fill from the left side. Lotsa blue here!</td>', 'Nice, I like how the frame is filled. Pretty even lighting, maybe more diffusion would be nice or a fill from the left side. Lotsa blue here!', '2004-08-03 19:23:37.000000', NULL, 1),
(840171, 95174, 22748, '<td valign="top">Really cool. Bad compression though!!! Please use a higher quality setting when saving to JPEG. It''s about 15KB, you have up to 150KB to use. Anyway, I like the angle and how the blue glow is coming from the light. Nice.</td>', 'Really cool. Bad compression though!!! Please use a higher quality setting when saving to JPEG. It''s about 15KB, you have up to 150KB to use. Anyway, I like the angle and how the blue glow is coming from the light. Nice.', '2004-08-03 19:32:49.000000', NULL, 1),
(840182, 95261, 22748, '<td valign="top">Great soft focus effect! Is it a Photoshop job, or a physical filter? The blue is so deep and wonderful, and the red lips are great. 9.</td>', 'Great soft focus effect! Is it a Photoshop job, or a physical filter? The blue is so deep and wonderful, and the red lips are great. 9.', '2004-08-03 19:39:52.000000', NULL, 1),
(840184, 94898, 22748, '<td valign="top">This is fabulous. I love how it flows over the border. The composition is perfection.</td>', 'This is fabulous. I love how it flows over the border. The composition is perfection.', '2004-08-03 19:41:23.000000', NULL, 1),
(840192, 95341, 22748, '<td valign="top">Pretty cool. Nice right blue on the headdress. Nice undistracting background. Lighting on the subject''s face is a little patchy and would be nice to be more even, but it''s okay.</td>', 'Pretty cool. Nice right blue on the headdress. Nice undistracting background. Lighting on the subject''s face is a little patchy and would be nice to be more even, but it''s okay.', '2004-08-03 19:53:04.000000', NULL, 1),
