(840202, 95027, 22748, '<td valign="top">Very nice. Very clean and neat composition. Interesting setting for the subject. I really like this one. 9</td>', 'Very nice. Very clean and neat composition. Interesting setting for the subject. I really like this one. 9', '2004-08-03 19:58:31.000000', NULL, 1),
(840205, 94551, 22748, '<td valign="top">Sorry, but where''s the BLUE? Did you read the challenge description?</td>', 'Sorry, but where''s the BLUE? Did you read the challenge description?', '2004-08-03 20:01:56.000000', NULL, 1),
(840206, 94953, 22748, '<td valign="top">Cool, nice shadows, nice bright colors.</td>', 'Cool, nice shadows, nice bright colors.', '2004-08-03 20:02:27.000000', NULL, 1),
(840213, 95200, 20066, '<td valign="top">It was supposed to be all blue I thought but since I like your foto and it is indeed of the moon and there is some blue on it I vote properly... I think 6.</td>', 'It was supposed to be all blue I thought but since I like your foto and it is indeed of the moon and there is some blue on it I vote properly... I think 6.', '2004-08-03 20:06:38.000000', NULL, 1),
(840221, 94972, 20066, '<td valign="top">You might have a use of a tripod!  Great photo if not that motion blur.</td>', 'You might have a use of a tripod!  Great photo if not that motion blur.', '2004-08-03 20:09:18.000000', NULL, 1),
(840223, 95025, 20066, '<td valign="top">Need a better dof I think.</td>', 'Need a better dof I think.', '2004-08-03 20:10:22.000000', NULL, 1),
(840224, 94555, 20066, '<td valign="top">It seems to me that the little glass on the right is not in as good focus as the other glasses.  But that is perhaps just because it is the runt!</td>', 'It seems to me that the little glass on the right is not in as good focus as the other glasses.  But that is perhaps just because it is the runt!', '2004-08-03 20:12:46.000000', NULL, 1),
(840229, 95160, 20066, '<td valign="top">Beautiful blue</td>', 'Beautiful blue', '2004-08-03 20:17:21.000000', NULL, 1),
(840234, 94974, 20066, '<td valign="top">Grainy pictures can be great but I''m not sure about this one.  Would have been better not so grainy.</td>', 'Grainy pictures can be great but I''m not sure about this one.  Would have been better not so grainy.', '2004-08-03 20:19:15.000000', NULL, 1),
(840235, 95325, 20066, '<td valign="top">Very simple and not bad at all.</td>', 'Very simple and not bad at all.', '2004-08-03 20:19:45.000000', NULL, 1),
(840240, 94794, 20066, '<td valign="top">Not in clear focus (or blurred) and the composition is to much centered for my taste.  AT least the flower, the tree or what it is in the foreground should have been offcentric.<br/>But it is the moon and it is blue so it can''t be all bad!</td>', 'Not in clear focus (or blurred) and the composition is to much centered for my taste.  AT least the flower, the tree or what it is in the foreground should have been offcentric.But it is the moon and it is blue so it can''t be all bad!', '2004-08-03 20:22:00.000000', NULL, 1),
(840245, 94574, 20066, '<td valign="top">Winter?  I think you live on the south part of the planet!</td>', 'Winter?  I think you live on the south part of the planet!', '2004-08-03 20:23:41.000000', NULL, 1),
(840250, 94675, 20066, '<td valign="top">Very good "color contrast".  I like it.</td>', 'Very good "color contrast".  I like it.', '2004-08-03 20:24:37.000000', NULL, 1),
