(843632, 94981, 23962, '<td valign="top">Shots like these are so hard to set up before the effect is lost. You must be happy. Great diagonals.</td>', 'Shots like these are so hard to set up before the effect is lost. You must be happy. Great diagonals.', '2004-08-05 00:26:42.000000', NULL, 1),
(843638, 94794, 23962, '<td valign="top">Simple and elegant.</td>', 'Simple and elegant.', '2004-08-05 00:28:28.000000', NULL, 1),
(843645, 95131, 23962, '<td valign="top">Wow, really pop art in the arrangement of colour and shapes. Caught my eye right away. You must be happy.</td>', 'Wow, really pop art in the arrangement of colour and shapes. Caught my eye right away. You must be happy.', '2004-08-05 00:30:48.000000', NULL, 1),
(843648, 94668, 23929, '<td valign="top">A little busy maybe?</td>', 'A little busy maybe?', '2004-08-05 00:31:05.000000', NULL, 1),
