INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(847462, 94643, 24659, '<td valign="top">I like this, even though I probably would''ve thought less of it if I took it.  But it stands out.</td>', 'I like this, even though I probably would''ve thought less of it if I took it.  But it stands out.', '2004-08-07 01:56:31.000000', NULL, 1),
(847465, 94921, 24659, '<td valign="top">Cute picture, cute baby, but I''d like to see it focused!  And the blanket''s a little much.</td>', 'Cute picture, cute baby, but I''d like to see it focused!  And the blanket''s a little much.', '2004-08-07 01:57:36.000000', NULL, 1),
(847499, 94754, 18552, '<td valign="top">Very simple but effective image. Love the color of the blue and the look of the glass.</td>', 'Very simple but effective image. Love the color of the blue and the look of the glass.', '2004-08-07 02:55:58.000000', NULL, 1),
(847500, 94898, 18552, '<td valign="top">Great idea! The lighting seems a bit over bright and the shadows a bit too dark.</td>', 'Great idea! The lighting seems a bit over bright and the shadows a bit too dark.', '2004-08-07 02:57:31.000000', NULL, 1),
(847502, 94712, 18552, '<td valign="top">Very nice idea. I think it would have come across better if the background had been a bit lighter and didn''t darken off to the left as much as it does.</td>', 'Very nice idea. I think it would have come across better if the background had been a bit lighter and didn''t darken off to the left as much as it does.', '2004-08-07 02:59:37.000000', NULL, 1),
(847503, 94878, 12902, '<td valign="top">Wonderful image. Full of grace and life. I wish it  will be a ribbon. Blue will become it very well. 10 from me</td>', 'Wonderful image. Full of grace and life. I wish it  will be a ribbon. Blue will become it very well. 10 from me', '2004-08-07 02:59:37.000000', NULL, 1),
(847505, 95025, 12902, '<td valign="top">Nice idea and very well realized. I like it. 8</td>', 'Nice idea and very well realized. I like it. 8', '2004-08-07 03:01:02.000000', NULL, 1),
(847509, 94668, 18552, '<td valign="top">Really a nice picture with a good feel to it. To me, the lighting seems too intense on the left side, the highlights look blown out.</td>', 'Really a nice picture with a good feel to it. To me, the lighting seems too intense on the left side, the highlights look blown out.', '2004-08-07 03:03:49.000000', NULL, 1),
(847511, 95051, 18552, '<td valign="top">Lots of nice shades of blue. Your picture has a bit of a snapshot kind of feel to it, perhaps it you had taken it from a different angle and not the whole person and bed -  it would have looded less like a snapshot and more like a photograph.</td>', 'Lots of nice shades of blue. Your picture has a bit of a snapshot kind of feel to it, perhaps it you had taken it from a different angle and not the whole person and bed -  it would have looded less like a snapshot and more like a photograph.', '2004-08-07 03:06:48.000000', NULL, 1),
(847512, 95192, 18552, '<td valign="top">Lovely color and great composition. To me, it would have been more effective if more of the dragon fly had been in focus than just it''s head.</td>', 'Lovely color and great composition. To me, it would have been more effective if more of the dragon fly had been in focus than just it''s head.', '2004-08-07 03:08:14.000000', NULL, 1),
(847513, 94802, 18552, '<td valign="top">Very good lighting and focus. The color looks a bit fakey.</td>', 'Very good lighting and focus. The color looks a bit fakey.', '2004-08-07 03:10:02.000000', NULL, 1),
(847515, 94745, 18552, '<td valign="top">Nice take on the challenge and good desat job!</td>', 'Nice take on the challenge and good desat job!', '2004-08-07 03:10:43.000000', NULL, 1),
(847517, 94937, 18552, '<td valign="top">Very intresting study. The folds in the cloth are great and I like the lighting, composition and focus a lot. However, to my eyes, the purple incense holder clashes with the lovely colors in the cloth.</td>', 'Very intresting study. The folds in the cloth are great and I like the lighting, composition and focus a lot. However, to my eyes, the purple incense holder clashes with the lovely colors in the cloth.', '2004-08-07 03:12:36.000000', NULL, 1),
(847518, 95222, 18552, '<td valign="top">Very nice, simple, effective photo - I like it a lot!</td>', 'Very nice, simple, effective photo - I like it a lot!', '2004-08-07 03:13:09.000000', NULL, 1),
(847520, 94932, 18552, '<td valign="top">Very nice picture, love the droplets and the focus on the flower. The color is a bit dull, this would be really fantastic if it were a bit brighter.</td>', 'Very nice picture, love the droplets and the focus on the flower. The color is a bit dull, this would be really fantastic if it were a bit brighter.', '2004-08-07 03:15:44.000000', NULL, 1),
(847522, 94902, 18552, '<td valign="top">To me, this looks really like a snapshot - I think a much tighter shot of the shirt would have been better.  The focus and color are really good.</td>', 'To me, this looks really like a snapshot - I think a much tighter shot of the shirt would have been better.  The focus and color are really good.', '2004-08-07 03:17:07.000000', NULL, 1),
(847525, 95061, 18552, '<td valign="top">Lovely, my pick for a ribbon. The lighting is a bit bright on the bottom but it pretty much looks like a perfect 10 to me!</td>', 'Lovely, my pick for a ribbon. The lighting is a bit bright on the bottom but it pretty much looks like a perfect 10 to me!', '2004-08-07 03:18:02.000000', NULL, 1),
(847526, 95016, 18552, '<td valign="top">Great job. Couldn''t really say how you could improve this as it''s lovely just the way it is.</td>', 'Great job. Couldn''t really say how you could improve this as it''s lovely just the way it is.', '2004-08-07 03:18:59.000000', NULL, 1),
(847527, 95125, 18552, '<td valign="top">What a lovely picture. I love all the colors and blue is the most dominant one - great photo for this challenge.</td>', 'What a lovely picture. I love all the colors and blue is the most dominant one - great photo for this challenge.', '2004-08-07 03:20:13.000000', NULL, 1),
