(847714, 94936, 22975, '<td valign="top">the contrasting colors are beautiful, and the black background was a great choice!</td>', 'the contrasting colors are beautiful, and the black background was a great choice!', '2004-08-07 09:08:13.000000', NULL, 1),
(847715, 95123, 22975, '<td valign="top">The simplicity of this shot is what makes it so good.  Just beautiful.  I wish I had taken it!</td>', 'The simplicity of this shot is what makes it so good.  Just beautiful.  I wish I had taken it!', '2004-08-07 09:10:47.000000', NULL, 1),
(847716, 94762, 22975, '<td valign="top">I just love HOW blue this is... and the composition is great.  Good job!<br/><br/><i>Message edited by author 2004-08-09 22:15:57.</i></td>', 'I just love HOW blue this is... and the composition is great.  Good job!', '2004-08-07 09:11:54.000000', '2004-08-09 23:15:57.000000', 1),
(847718, 94638, 22975, '<td valign="top">The focus on this is perfect!</td>', 'The focus on this is perfect!', '2004-08-07 09:12:38.000000', NULL, 1),
