(847742, 95315, 23053, '<td valign="top">I think cropping would have helped - the lockers look like they''re falling over on the right side (which is probably due to the camera''s barrel distortion).</td>', 'I think cropping would have helped - the lockers look like they''re falling over on the right side (which is probably due to the camera''s barrel distortion).', '2004-08-07 09:39:35.000000', NULL, 1),
(847745, 95325, 23053, '<td valign="top">Niiiiiiiiice contrast. 8.</td>', 'Niiiiiiiiice contrast. 8.', '2004-08-07 09:40:53.000000', NULL, 1),
(847749, 94685, 23053, '<td valign="top">I would have liked to see the cup rotated just a bit so that the logo is in the light and the handle is closer to the camera.  4.</td>', 'I would have liked to see the cup rotated just a bit so that the logo is in the light and the handle is closer to the camera.  4.', '2004-08-07 09:42:30.000000', NULL, 1),
(847752, 94675, 23053, '<td valign="top">For me, the yellow stands out more here than the blue.  5.</td>', 'For me, the yellow stands out more here than the blue.  5.', '2004-08-07 09:44:23.000000', NULL, 1),
(847754, 94693, 23053, '<td valign="top">This photo seems to highlight the white flower over the blue.  5.</td>', 'This photo seems to highlight the white flower over the blue.  5.', '2004-08-07 09:46:40.000000', NULL, 1),
(847758, 94929, 23053, '<td valign="top">I would have liked a greater DOF so that both eyes were in focus.  Aside from that, this is nice.  6.</td>', 'I would have liked a greater DOF so that both eyes were in focus.  Aside from that, this is nice.  6.', '2004-08-07 09:49:48.000000', NULL, 1),
(847768, 94626, 24486, '<td valign="top">Love the title.Good colour tone</td>', 'Love the title.Good colour tone', '2004-08-07 10:09:40.000000', NULL, 1),
(847791, 94782, 24486, '<td valign="top">The white background may have let you down in this photograph. It helps to highlight the tones of the fingers and the contents of the glass but it has made parts of the flowing liquid and that great looking drip forming on the bottom of the glass partially invisible. Good use of a fast shutter speed; the flowing liquid looks real smooth. Good luck</td>', 'The white background may have let you down in this photograph. It helps to highlight the tones of the fingers and the contents of the glass but it has made parts of the flowing liquid and that great looking drip forming on the bottom of the glass partially invisible. Good use of a fast shutter speed; the flowing liquid looks real smooth. Good luck', '2004-08-07 10:29:13.000000', NULL, 1),
(847796, 95273, 24486, '<td valign="top">Good timing and perspective.</td>', 'Good timing and perspective.', '2004-08-07 10:32:27.000000', NULL, 1),
(847798, 95340, 24486, '<td valign="top">Great DOF</td>', 'Great DOF', '2004-08-07 10:33:33.000000', NULL, 1),
