INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(969578, 95331, 2553, '<td valign="top">I love the reflections of the water, and the bubbles.  I would have like to have seen the composition of the line and the girl on more of an angle, and also would have preferred to see her "arrow straight" with her legs straight out and her arms by her sides, so that she mirrored the line.</td>', 'I love the reflections of the water, and the bubbles.  I would have like to have seen the composition of the line and the girl on more of an angle, and also would have preferred to see her "arrow straight" with her legs straight out and her arms by her sides, so that she mirrored the line.', '2004-10-22 08:20:02.000000', NULL, 0),
(972660, 94774, 18722, '<td valign="top">Most shots are not cropped tight enough -- the photographer just does not get close enough to the subject.  Looking at this image, I think you have found an image that just the opposite is true -- I think this image is begging for more negative space above it and probably to one side or the other.<br/> <br/>Great idea with wonderful lighting and colors.<br/> <br/>David</td>', 'Most shots are not cropped tight enough -- the photographer just does not get close enough to the subject.  Looking at this image, I think you have found an image that just the opposite is true -- I think this image is begging for more negative space above it and probably to one side or the other. Great idea with wonderful lighting and colors. David', '2004-10-25 08:21:01.000000', NULL, 0),
(981524, 94720, 10818, '<td valign="top">Wow, what a fantastic photo.  The vivid blue and the desat are awesome.</td>', 'Wow, what a fantastic photo.  The vivid blue and the desat are awesome.', '2004-10-31 15:46:25.000000', NULL, 0),
(1102339, 94723, 31916, '<td valign="top">Thanks for the nice shot and inspiration.  I keep driving by this building trying to decide how to shoot it.  I got all caught up in the angles and didn''t even think about the clouds.  Good job!!</td>', 'Thanks for the nice shot and inspiration.  I keep driving by this building trying to decide how to shoot it.  I got all caught up in the angles and didn''t even think about the clouds.  Good job!!', '2005-01-11 21:40:10.000000', NULL, 0),
(1191193, 95140, 32767, '<td valign="top">This is a fantastic photo. What did you do to get such soft but rich colors. Dare I say...breathtaking?<br/> <br/>Wow, nice job.</td>', 'This is a fantastic photo. What did you do to get such soft but rich colors. Dare I say...breathtaking? Wow, nice job.', '2005-02-23 15:47:23.000000', NULL, 0),
(1356161, 94975, 8860, '<td valign="top">Beautiful and simple image.</td>', 'Beautiful and simple image.', '2005-05-03 17:51:31.000000', NULL, 0),
(1416647, 95000, 38413, '<td valign="top">great pic</td>', 'great pic', '2005-05-27 21:33:38.000000', NULL, 0),
(1436636, 94920, 8367, '<td valign="top">This is an amazing shot. The colors and detail are brilliant!<br/>(I went to Oshkosh way back when I was attending A&amp;P school...back in my Pentax K1000 days...got some great pics...but nuttin'' like this!)<br/>Excellent capture.</td>', 'This is an amazing shot. The colors and detail are brilliant!(I went to Oshkosh way back when I was attending A&P school...back in my Pentax K1000 days...got some great pics...but nuttin'' like this!)Excellent capture.', '2005-06-06 12:46:34.000000', NULL, 0),
(1472029, 94916, 15711, '<td valign="top">Really perfect for that challenge.  It has great detail and I love the saturation of color in the eye.  GREAT!</td>', 'Really perfect for that challenge.  It has great detail and I love the saturation of color in the eye.  GREAT!', '2005-06-21 21:17:32.000000', NULL, 0),
(1481877, 94721, 16488, '<td valign="top">Looks like you were a victim of people adhering too closely to the "rules" of composition!  With the expression on this chaps face, he should be about to hit the frame!  Ahh, well, you know the voters....when in doubt, it must be a 5.<br/> <br/>Thanks for playing closest to 5 today!</td>', 'Looks like you were a victim of people adhering too closely to the "rules" of composition!  With the expression on this chaps face, he should be about to hit the frame!  Ahh, well, you know the voters....when in doubt, it must be a 5. Thanks for playing closest to 5 today!', '2005-06-24 19:09:10.000000', NULL, 0),
(1481883, 94721, 19035, '<td valign="top">I took this shot nearly a year ago, Ive learned quite a bit since then, but I stil love this candid shot.  Thanks for commenting.<br/><br/><i>Message edited by author 2005-06-24 18:24:32.</i></td>', 'I took this shot nearly a year ago, Ive learned quite a bit since then, but I stil love this candid shot.  Thanks for commenting.', '2005-06-24 19:13:55.000000', '2005-06-24 19:24:32.000000', 0),
