(1695849, 94668, 36628, '<td valign="top">This would make a great shot to hang in a bar! Although I might be biased since its one of my all time favorite drinks...:)</td>', 'This would make a great shot to hang in a bar! Although I might be biased since its one of my all time favorite drinks...:)', '2005-09-11 20:01:54.000000', NULL, 0),
(2558313, 94874, 32813, '<td valign="top">Well done.  Captured a soothing effect.</td>', 'Well done.  Captured a soothing effect.', '2006-06-27 15:29:24.000000', NULL, 0),
(2996727, 95334, 34659, '<td valign="top">I like this - the deep moody tones and the dark vignetting work well with the subject.  Keep up the good work!  Stuff like this isn''t everyone''s cup of tea, but I love surreal images.</td>', 'I like this - the deep moody tones and the dark vignetting work well with the subject.  Keep up the good work!  Stuff like this isn''t everyone''s cup of tea, but I love surreal images.', '2006-11-04 00:52:11.000000', NULL, 0),
